query HomeScreen($city: String!, $first: Int!) {
  restaurants(near: $city, first: $first) {
    name
    rating
    deliveryMinutes
    photoUrl
    offers { title }
  }
  pageInfo { hasNextPage endCursor }
}

message Order {
  string id = 1;
  int64 amount_paise = 2;
  string city = 3;
}
service Orders {
  rpc GetOrder(GetOrderRequest) returns (Order);
  rpc WatchOrder(GetOrderRequest) returns (stream OrderEvent);
}

